def normalize_labels(items):
    if not isinstance(items, list) or not all(isinstance(x, str) for x in items):
        raise TypeError("items must be a list of str")
    result = []
    seen = set()
    for item in items:
        key = item.strip()
        if not key:
            continue
        folded = key.casefold()
        if folded not in seen:
            seen.add(folded)
            result.append(key)
    return result
